CREATE TYPE public.app_role AS ENUM ('master_admin');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL DEFAULT 'master_admin', UNIQUE(role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own administrator assignment" ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.is_master_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='master_admin') $$;
REVOKE ALL ON FUNCTION public.is_master_admin() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_master_admin() TO authenticated,service_role;
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, customer_id text UNIQUE NOT NULL DEFAULT ('SDE-C-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,12))), first_name text NOT NULL DEFAULT '', last_name text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', address text NOT NULL DEFAULT '', city text NOT NULL DEFAULT '', state text NOT NULL DEFAULT '', country text NOT NULL DEFAULT '', avatar_path text NOT NULL DEFAULT '', account_status text NOT NULL DEFAULT 'active' CHECK(account_status IN ('active','suspended','deactivated')), suspension_reason text NOT NULL DEFAULT '', updated_by uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own profile or master administrator" ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid() OR public.is_master_admin());
INSERT INTO public.profiles(id) SELECT id FROM auth.users ON CONFLICT(id) DO NOTHING;
CREATE FUNCTION public.create_customer_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id) VALUES(NEW.id) ON CONFLICT(id) DO NOTHING; RETURN NEW; END $$;
CREATE TRIGGER create_customer_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_customer_profile();
CREATE TABLE public.admin_settings (id boolean PRIMARY KEY DEFAULT true CHECK(id), currency text NOT NULL DEFAULT 'USD', timezone text NOT NULL DEFAULT 'UTC', idle_minutes integer NOT NULL DEFAULT 30 CHECK(idle_minutes BETWEEN 5 AND 120), require_mfa boolean NOT NULL DEFAULT false, notification_preferences jsonb NOT NULL DEFAULT '{}', updated_by uuid);
GRANT SELECT ON public.admin_settings TO authenticated; GRANT ALL ON public.admin_settings TO service_role; ALTER TABLE public.admin_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Master settings" ON public.admin_settings FOR SELECT TO authenticated USING(public.is_master_admin());
CREATE TABLE public.admin_sessions (session_id text PRIMARY KEY, user_id uuid NOT NULL, last_seen timestamptz NOT NULL DEFAULT now(), ended_at timestamptz);
GRANT ALL ON public.admin_sessions TO service_role; ALTER TABLE public.admin_sessions ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.admin_activity (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid, action text NOT NULL, entity_type text NOT NULL, entity_id text, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.admin_activity TO authenticated; GRANT SELECT,INSERT ON public.admin_activity TO service_role; ALTER TABLE public.admin_activity ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Master reads audit records" ON public.admin_activity FOR SELECT TO authenticated USING(public.is_master_admin());
CREATE FUNCTION public.prevent_audit_changes() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Audit records are immutable'; END $$;
CREATE TRIGGER immutable_admin_activity BEFORE UPDATE OR DELETE ON public.admin_activity FOR EACH ROW EXECUTE FUNCTION public.prevent_audit_changes();
CREATE FUNCTION public.audit_operation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE row_data jsonb; BEGIN row_data=to_jsonb(NEW); IF row_data->>'updated_by' IS NOT NULL THEN INSERT INTO public.admin_activity(actor_id,action,entity_type,entity_id,details) VALUES((row_data->>'updated_by')::uuid,lower(TG_OP),TG_TABLE_NAME,row_data->>'id',jsonb_build_object('before',CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) ELSE NULL END,'after',row_data)); END IF; RETURN NEW; END $$;
ALTER TABLE public.shipments ADD COLUMN sender_email text NOT NULL DEFAULT '', ADD COLUMN sender_phone text NOT NULL DEFAULT '', ADD COLUMN sender_address text NOT NULL DEFAULT '', ADD COLUMN sender_city text NOT NULL DEFAULT '', ADD COLUMN sender_state text NOT NULL DEFAULT '', ADD COLUMN sender_country text NOT NULL DEFAULT '', ADD COLUMN recipient_email text NOT NULL DEFAULT '', ADD COLUMN recipient_phone text NOT NULL DEFAULT '', ADD COLUMN recipient_address text NOT NULL DEFAULT '', ADD COLUMN recipient_city text NOT NULL DEFAULT '', ADD COLUMN recipient_state text NOT NULL DEFAULT '', ADD COLUMN recipient_country text NOT NULL DEFAULT '', ADD COLUMN parcel_description text NOT NULL DEFAULT '', ADD COLUMN parcel_weight numeric NOT NULL DEFAULT 0, ADD COLUMN shipment_type text NOT NULL DEFAULT 'Domestic Courier Delivery', ADD COLUMN shipping_cost numeric NOT NULL DEFAULT 0, ADD COLUMN currency text NOT NULL DEFAULT 'USD', ADD COLUMN cancelled_at timestamptz, ADD COLUMN updated_by uuid;
CREATE TRIGGER audit_shipments AFTER INSERT OR UPDATE ON public.shipments FOR EACH ROW EXECUTE FUNCTION public.audit_operation();
CREATE TRIGGER audit_profiles AFTER INSERT OR UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.audit_operation();
CREATE TRIGGER audit_settings AFTER INSERT OR UPDATE ON public.admin_settings FOR EACH ROW EXECUTE FUNCTION public.audit_operation();
ALTER TABLE public.shipment_events ADD COLUMN updated_by uuid, ADD COLUMN proof_path text, ADD COLUMN delivery_verified boolean NOT NULL DEFAULT false;
CREATE TRIGGER audit_tracking AFTER INSERT OR UPDATE ON public.shipment_events FOR EACH ROW EXECUTE FUNCTION public.audit_operation();
ALTER TABLE public.service_requests ADD COLUMN updated_by uuid;
CREATE TRIGGER audit_support_requests AFTER UPDATE ON public.service_requests FOR EACH ROW EXECUTE FUNCTION public.audit_operation();
CREATE TABLE public.delivery_personnel (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, email text NOT NULL, phone text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true, updated_by uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.delivery_personnel TO authenticated; GRANT ALL ON public.delivery_personnel TO service_role; ALTER TABLE public.delivery_personnel ENABLE ROW LEVEL SECURITY; CREATE POLICY "Master personnel" ON public.delivery_personnel FOR SELECT TO authenticated USING(public.is_master_admin()); CREATE TRIGGER audit_personnel AFTER INSERT OR UPDATE ON public.delivery_personnel FOR EACH ROW EXECUTE FUNCTION public.audit_operation();
CREATE TABLE public.delivery_assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), shipment_id uuid NOT NULL REFERENCES public.shipments(id), driver_id uuid NOT NULL REFERENCES public.delivery_personnel(id), notes text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'assigned', updated_by uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.delivery_assignments TO authenticated; GRANT ALL ON public.delivery_assignments TO service_role; ALTER TABLE public.delivery_assignments ENABLE ROW LEVEL SECURITY; CREATE POLICY "Master assignments" ON public.delivery_assignments FOR SELECT TO authenticated USING(public.is_master_admin()); CREATE TRIGGER audit_assignments AFTER INSERT OR UPDATE ON public.delivery_assignments FOR EACH ROW EXECUTE FUNCTION public.audit_operation();
CREATE TABLE public.payment_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), shipment_id uuid REFERENCES public.shipments(id), provider text NOT NULL, provider_reference text UNIQUE NOT NULL, amount numeric NOT NULL, currency text NOT NULL, status text NOT NULL CHECK(status IN ('pending','paid','refunded','failed')), verified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.payment_records TO authenticated; GRANT ALL ON public.payment_records TO service_role; ALTER TABLE public.payment_records ENABLE ROW LEVEL SECURITY; CREATE POLICY "Master payment reads" ON public.payment_records FOR SELECT TO authenticated USING(public.is_master_admin());
CREATE TABLE public.support_replies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES public.service_requests(id), message text NOT NULL, updated_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.support_replies TO authenticated; GRANT ALL ON public.support_replies TO service_role; ALTER TABLE public.support_replies ENABLE ROW LEVEL SECURITY; CREATE POLICY "Master support replies" ON public.support_replies FOR SELECT TO authenticated USING(public.is_master_admin()); CREATE TRIGGER audit_replies AFTER INSERT OR UPDATE ON public.support_replies FOR EACH ROW EXECUTE FUNCTION public.audit_operation();
CREATE TABLE public.customer_notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, shipment_id uuid REFERENCES public.shipments(id), category text NOT NULL, title text NOT NULL, message text NOT NULL, read_at timestamptz, updated_by uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.customer_notifications TO authenticated; GRANT ALL ON public.customer_notifications TO service_role; ALTER TABLE public.customer_notifications ENABLE ROW LEVEL SECURITY; CREATE POLICY "Own in-app notifications or master" ON public.customer_notifications FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_master_admin()); CREATE POLICY "Read own notifications" ON public.customer_notifications FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid()); REVOKE UPDATE ON public.customer_notifications FROM authenticated; GRANT UPDATE(read_at) ON public.customer_notifications TO authenticated; CREATE TRIGGER audit_notifications AFTER INSERT OR UPDATE ON public.customer_notifications FOR EACH ROW EXECUTE FUNCTION public.audit_operation();
CREATE TABLE public.website_content (id boolean PRIMARY KEY DEFAULT true CHECK(id), draft jsonb NOT NULL DEFAULT '{}', published jsonb NOT NULL DEFAULT '{}', published_at timestamptz, updated_by uuid);
GRANT SELECT ON public.website_content TO anon,authenticated; GRANT ALL ON public.website_content TO service_role; ALTER TABLE public.website_content ENABLE ROW LEVEL SECURITY; CREATE POLICY "Published content reads" ON public.website_content FOR SELECT TO anon,authenticated USING(true); REVOKE SELECT ON public.website_content FROM anon,authenticated; GRANT SELECT(published,published_at) ON public.website_content TO anon,authenticated; CREATE TRIGGER audit_website AFTER INSERT OR UPDATE ON public.website_content FOR EACH ROW EXECUTE FUNCTION public.audit_operation();
CREATE FUNCTION public.admin_tracking_event(p_shipment_id uuid,p_status text,p_location text,p_description text,p_occurred_at timestamptz,p_actor uuid,p_verified boolean,p_event_id uuid DEFAULT NULL,p_proof_path text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE event_id uuid; BEGIN IF NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=p_actor AND role='master_admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; IF p_status NOT IN ('Shipment Registered','Picked Up','Processing','In Transit','Arrived at Sorting Facility','Departed Facility','Out for Delivery','Delivered','Delivery Attempted','Delayed','Exception') THEN RAISE EXCEPTION 'Invalid status'; END IF; IF p_status='Delivered' AND NOT p_verified THEN RAISE EXCEPTION 'Delivery must be verified'; END IF; IF p_occurred_at>now()+interval '1 minute' THEN RAISE EXCEPTION 'Future tracking events are not allowed'; END IF; IF NOT EXISTS(SELECT 1 FROM public.shipments WHERE id=p_shipment_id AND cancelled_at IS NULL) THEN RAISE EXCEPTION 'Shipment unavailable'; END IF; IF p_event_id IS NULL THEN INSERT INTO public.shipment_events(shipment_id,status,location,description,occurred_at,updated_by,delivery_verified,proof_path) VALUES(p_shipment_id,p_status,p_location,p_description,p_occurred_at,p_actor,p_verified,p_proof_path) RETURNING id INTO event_id; ELSE UPDATE public.shipment_events SET status=p_status,location=p_location,description=p_description,occurred_at=p_occurred_at,updated_by=p_actor,delivery_verified=p_verified,proof_path=p_proof_path WHERE id=p_event_id AND shipment_id=p_shipment_id RETURNING id INTO event_id; IF event_id IS NULL THEN RAISE EXCEPTION 'Event not found'; END IF; END IF; UPDATE public.shipments SET status=CASE WHEN latest.status IN ('Departed Facility') THEN 'In Transit' WHEN latest.status IN ('Delayed','Exception') THEN 'Exception / Delayed' ELSE latest.status END,latest_location=latest.location,updated_by=p_actor FROM (SELECT status,location FROM public.shipment_events WHERE shipment_id=p_shipment_id ORDER BY occurred_at DESC LIMIT 1) latest WHERE id=p_shipment_id; INSERT INTO public.customer_notifications(user_id,shipment_id,category,title,message,updated_by) SELECT user_id,id,'shipment',p_status,p_location||' — '||p_description,p_actor FROM public.shipments WHERE id=p_shipment_id AND user_id IS NOT NULL; RETURN event_id; END $$;
REVOKE ALL ON FUNCTION public.admin_tracking_event(uuid,text,text,text,timestamptz,uuid,boolean,uuid,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.admin_tracking_event(uuid,text,text,text,timestamptz,uuid,boolean,uuid,text) TO service_role;
CREATE POLICY "Master reads shipments" ON public.shipments FOR SELECT TO authenticated USING(public.is_master_admin()); CREATE POLICY "Master reads events" ON public.shipment_events FOR SELECT TO authenticated USING(public.is_master_admin()); CREATE POLICY "Master reads requests" ON public.service_requests FOR SELECT TO authenticated USING(public.is_master_admin());